example.inefficient_code:
// Recomputing expensive operation in loop
for (let i = 0; i < 1000; i++) {
  const result = expensiveCalculation(data);
  processResult(result);
}

example.optimized_code:
// Cache expensive computation
const cachedResult = expensiveCalculation(data);
for (let i = 0; i < 1000; i++) {
  processResult(cachedResult);
}

example.poor_code:
function processUserData(userData) {
  // Validate input
  if (!userData || typeof userData !== 'object') {
    throw new Error('Invalid user data');
  }

  // Sanitize data
  const cleanData = {
    name: userData.name.trim(),
    email: userData.email.toLowerCase().trim(),
    age: parseInt(userData.age)
  };

  // Save to database
  const connection = require('./db').getConnection();
  connection.query('INSERT INTO users SET ?', cleanData);

  // Send welcome email
  const emailService = require('./email');
  emailService.send(cleanData.email, 'Welcome!');

  // Log activity
  const logger = require('./logger');
  logger.info(`User ${cleanData.name} registered`);

  // Return result
  return { success: true, userId: connection.insertId };
}

example.improved_code:
function validateUserData(userData) {
  if (!userData || typeof userData !== 'object') {
    throw new Error('Invalid user data');
  }

  return {
    name: userData.name.trim(),
    email: userData.email.toLowerCase().trim(),
    age: parseInt(userData.age)
  };
}

function sanitizeUserData(userData) {
  return {
    name: userData.name.trim(),
    email: userData.email.toLowerCase().trim(),
    age: parseInt(userData.age)
  };
}

async function saveUserToDatabase(userData) {
  const connection = require('./db').getConnection();
  const result = await connection.query('INSERT INTO users SET ?', userData);
  return result.insertId;
}

async function sendWelcomeEmail(email, name) {
  const emailService = require('./email');
  await emailService.send(email, 'Welcome!');
}

function logUserActivity(name) {
  const logger = require('./logger');
  logger.info(`User ${name} registered`);
}

async function processUserData(userData) {
  const cleanData = sanitizeUserData(validateUserData(userData));
  const userId = await saveUserToDatabase(cleanData);
  await sendWelcomeEmail(cleanData.email, cleanData.name);
  logUserActivity(cleanData.name);

  return { success: true, userId };
}

